{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    # Validate required fields
    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(core_distance, dict):
        raise ValueError("core_distance must be a dict")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")
    for n in nodes:
        if n not in core_distance:
            raise ValueError(f"Missing core_distance for node {n}")

    # Compute mutual reachability weight for each edge
    mr_edges = []
    for edge in distances:
        if len(edge) != 3:
            raise ValueError("Each distance entry must have exactly 3 elements")
        u, v, d = edge[0], edge[1], edge[2]
        if u not in core_distance:
            raise ValueError(f"Unknown node in distances: {u}")
        if v not in core_distance:
            raise ValueError(f"Unknown node in distances: {v}")
        # Canonicalize undirected endpoints: smaller label first
        if u > v:
            u, v = v, u
        mr = max(core_distance[u], core_distance[v], d)
        mr_edges.append((u, v, mr))

    # Deterministic sort: by mutual reachability weight, then first endpoint, then second
    mr_edges.sort(key=lambda e: (e[2], e[0], e[1]))

    # Union-Find for Kruskal's MST
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    needed = len(nodes) - 1

    for u, v, w in mr_edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == needed:
                break

    if len(mst_edges) != needed:
        raise ValueError("Graph is disconnected; cannot form a spanning tree")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
